rows.Expression:
COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        [_Project Overall Risk Score] >= 40
    )
)

COUNTROWS(
    FILTER(
        VALUES('Resources'[ResourceID]),
        [% Utilization] > 1
    )
)

COUNTROWS(
    FILTER(
        VALUES('Resources'[ResourceID]),
        [% Utilization] > 1.2
    )
)

COUNTROWS(
    FILTER(
        VALUES('Resources'[ResourceID]),
        COALESCE([_Resource Demand Hours], 0) = 0
    )
)

COUNTROWS(
    FILTER(
        VALUES('Resources'[ResourceID]),
        COALESCE([_CapacityHoursNetto], 0) = 0
    )
)

COUNTROWS(
    FILTER(
        VALUES('Resources'[ResourceID]),
        ISBLANK(CALCULATE(SELECTEDVALUE('Resources'[DepartmentID])))
    )
)

MINX(
    FILTER(
        'Tasks',
        (
            'Tasks'[IsMilestoneID] = TRUE()
            || LOWER(COALESCE('Tasks'[Is Milestone], "")) IN { "yes", "true", "1" }
            || NOT(ISBLANK('Tasks'[Milestone]))
        )
            && NOT(ISBLANK('Tasks'[Finish Date]))
            && 'Tasks'[Finish Date] >= TODAY()
    ),
    'Tasks'[Finish Date]
)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE([Status Report Is Overdue]) = 1
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE(COUNTROWS(FILTER('Projects', ISBLANK('Projects'[Finish Date])))) > 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE(COUNTROWS(FILTER('Projects', ISBLANK('Projects'[Project Owner]) || TRIM('Projects'[Project Owner]) = ""))) > 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE(COUNTROWS('Risks')) = 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE([Open Actions]) = 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE(
            COUNTROWS(
                FILTER(
                    'Projects',
                    ISBLANK('Projects'[gbl_baselinestart])
                        || ISBLANK('Projects'[gbl_baselinefinish])
                )
            )
        ) > 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE([Overdue Actions]) > 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE([Overdue Issues]) > 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE([Project Health Score]) < 60
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE([Project Health Score]) < 40
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE(
            COUNTROWS(
                FILTER(
                    'Projects',
                    (
                        NOT(ISBLANK('Projects'[Finish Date]))
                            && NOT(ISBLANK('Projects'[gbl_baselinefinish]))
                            && 'Projects'[Finish Date] > 'Projects'[gbl_baselinefinish]
                    )
                    || (
                        NOT(ISBLANK('Projects'[Finish Date]))
                            && 'Projects'[Finish Date] < TODAY()
                            && COALESCE('Projects'[Progress], 0) < 1
                    )
                )
            )
        ) > 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE([Executive Attention Flag]) = 1
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE(
            COUNTROWS(
                FILTER(
                    'Projects',
                    CONTAINSSTRING(LOWER(COALESCE('Projects'[Program Name], "")), "strateg")
                        || CONTAINSSTRING(LOWER(COALESCE('Projects'[Tagging], "")), "strateg")
                        || CONTAINSSTRING(LOWER(COALESCE('Projects'[Project Type], "")), "strateg")
                )
            )
        ) > 0
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE(
            COUNTROWS(
                FILTER(
                    'Projects',
                    CONTAINSSTRING(LOWER(COALESCE('Projects'[Program Name], "")), "strateg")
                        || CONTAINSSTRING(LOWER(COALESCE('Projects'[Tagging], "")), "strateg")
                        || CONTAINSSTRING(LOWER(COALESCE('Projects'[Project Type], "")), "strateg")
                )
            )
        ) > 0
            && CALCULATE([Project Health Score]) < 60
    )
), 0)

COALESCE(COUNTROWS(
    FILTER(
        VALUES('Projects'[ProjectID]),
        CALCULATE([Executive Attention Flag]) = 1
    )
), 0)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE(SUM('Projects'[Budget Cost])) = 0
                && CALCULATE(SUM('Projects'[gbl_totalprojectbudget])) = 0
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE(
                COUNTROWS(
                    FILTER('Projects', ISBLANK('Projects'[Phase]) || TRIM('Projects'[Phase]) = "")
                )
            ) > 0
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE([Status Report Is Overdue]) = 0
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE([Latest Status Completeness %]) < 0.8
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE(COUNTROWS('VollständigePhasenListe')) = 0
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE(COUNTROWS('VollständigePhasenListe')) > 0
                && CALCULATE(COUNTROWS('DimPhasen')) = 0
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE([Project Has PMO Exception]) = 1
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE([Open Decisions]) > 0
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE([PMO Review Priority Score]) >= 60
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE([Executive Attention Flag]) = 1
                || CALCULATE([PMO Critical Exception Count]) > 0
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE([Capacity Gap Hours]) > 0
                && CALCULATE([Project Health Score]) < 70
        )
    ),
    0
)

COALESCE(
    COUNTROWS(
        FILTER(
            VALUES('Projects'[ProjectID]),
            CALCULATE([Is Strategic Project]) = 0
        )
    ),
    0
)
